#!/usr/bin/env bash
# alle4.sh - Abnahme 4 Spur AN: alle Fensterlaeufe NACHEINANDER (keine Parallel-Last, kein ctest daneben).
# Basis wie Abnahme 3 (abn3_alle.sh), damit die state.log-Dateien Zeile fuer Zeile vergleichbar sind; Bilder per RE15_FRAMEDUMP
# mit relativem Praefix (Arbeitsverzeichnis = Laufordner).
W=$(dirname "$0"); L=$W/lauf4.sh
BASIS="RE15_DEBUG_JUMP=6000@250 RE15_PLAYER_POS=1763,-9700,1024,2 RE15_SET_FLAG=3:48,3:49,3:100,3:239,4:23,3:89,3:22"
J5090="RE15_DEBUG_JUMP=5090@250 RE15_PLAYER_POS=500,-9175,2048,0 RE15_INPUT_SCRIPT_BASIS=spiel RE15_INPUT_SCRIPT_START=100"
# 1-4: Wiederholung der Abnahme-3-Laeufe (Vergleich NB4 -> NB5)
bash $L z6030 300 $W/eingabe_kette.txt $BASIS RE15_SE_DEBUG=1 RE15_EXIT_AT=1700#6030 RE15_FRAMEDUMP=1440-1600/4:f
bash $L s5090 420 $W/eingabe_kette.txt $BASIS RE15_SE_DEBUG=1 RE15_EXIT_AT=1965#5090 RE15_FRAMEDUMP=1150-1960/15:f
bash $L kampf 700 $W/eingabe_kette_kampf.txt $BASIS RE15_SE_DEBUG=1 RE15_EQUIP=3 RE15_GIVE=3:400,21:250 RE15_EXIT_AT=5400#5090 RE15_FRAMEDUMP=1700-5400/50:f
bash $L leiche_west 150 /dev/stdin $J5090 RE15_SET_FLAG=3:89,9:133,3:42 RE15_EXIT_AT=1100#5090 RE15_FRAMEDUMP=300-700/5:f <<<"A0.1,W1,U16,W10"
# 5-6: Schuesse in Wagen C vor der Szene (Annette lebt, hp -1; Riesenform 0x30 steht dahinter)
bash $L an_vorszene 300 /dev/stdin $J5090 RE15_SET_FLAG=3:89,9:133 RE15_EQUIP=3 RE15_GIVE=3:100 RE15_EXIT_AT=1300#5090 RE15_FRAMEDUMP=130-1300/10:f <<<"A0.1,W1,U2,MA3,U8.5,W45"
bash $L an_durch 150 /dev/stdin $J5090 RE15_SET_FLAG=3:89,9:133 RE15_EQUIP=3 RE15_GIVE=3:100 "RE15_GEGNER_POS=1,600,-23550,2048@120#5090" RE15_EXIT_AT=400#5090 RE15_FRAMEDUMP=130-400/10:f <<<"A0.1,W1,U2,MA4,W2"
# 7: ROOM6000, Annette geht nach dem Gespraech (Aot Slot 4 -> sub02 @0x00F84) in den Zug (Wand-Klemme/Schub mit dem 0x4D-Kasten)
bash $L an6000 200 /dev/stdin RE15_DEBUG_JUMP=6000@250 RE15_PLAYER_POS=4550,-8200,1024,2 RE15_SET_FLAG=3:48,3:49,3:100 RE15_INPUT_SCRIPT_BASIS=spiel RE15_INPUT_SCRIPT_START=100 RE15_EXIT_AT=1500#6000 RE15_FRAMEDUMP=100-1500/20:f <<<"W1,A0.1,W1,A0.1,W1,A0.1,W40"
# 8-9: Elza
bash $L elza5091 300 /dev/stdin RE15_DEBUG_JUMP=5091@250 RE15_TITLE_SHOT_CHAR=1 RE15_PLAYER_POS=500,-9175,2048,0 RE15_INPUT_SCRIPT_BASIS=spiel RE15_INPUT_SCRIPT_START=100 RE15_SET_FLAG=3:89,9:133 RE15_EQUIP=3 RE15_GIVE=3:100 RE15_EXIT_AT=1300#5091 RE15_FRAMEDUMP=100-1300/20:f <<<"A0.1,W1,U2,MA3,U8.5,W30"
bash $L elza_10d0 150 /dev/stdin RE15_TITLE_SHOT_CHAR=1 RE15_DEBUG_JUMP=10D0@250 RE15_PLAYER_POS=3800,23625,0,0 "RE15_GEGNER_POS=2,6750,23625,2048@1#10D0" RE15_EQUIP=3 RE15_GIVE=3:100 RE15_INPUT_SCRIPT_BASIS=spiel RE15_INPUT_SCRIPT_START=100 RE15_EXIT_AT=520#10D0 RE15_FRAMEDUMP=280-520/12:f <<<"W6,MA6,W1"
echo ALLE-FERTIG
